        n = len(v)
        nums = [x for x in v if isinstance(x,(int,float))]
        if nums and len(nums)==n:
            return f'list[{n}] range=[{min(nums):.4g}, {max(nums):.4g}] head={v[:3]}'
        if v and isinstance(v[0], dict):
            return f'list[{n}] of dict keys={list(v[0].keys())[:10]}'
        if v and isinstance(v[0], list):
            return f'list[{n}] of list[{len(v[0])}]'
        return f'list[{n}] head={str(v[:3])[:80]}'
    if isinstance(v, dict) and depth < 2:
        return 'dict{' + ', '.join(f'{k}: {summarize(x, depth+1)}' for k,x in list(v.items())[:14]) + '}'
    if isinstance(v, dict):
        return f'dict keys={list(v.keys())[:12]}'
    return f'{type(v).__name__}={str(v)[:70]}'
