    border-radius: 0 6px 6px 0; padding: 12px 14px;
  }
  .layer-name { font-size: 13px; color: var(--c-muted); margin-bottom: 8px; font-weight: 600; }
  /* ⛔ 绝不用 repeat(auto-fit, minmax(...,1fr))：在 fit-content 父容器里 1fr 解析成
     min-content → 整栅格塌成单列 → 图被拉成 347×998（比例 2.88，占页超标 2 倍以上）。
     实测坐实。必须写【显式列数 + 定宽】，模块才真正横排。 */
  .modules { display: grid; grid-template-columns: repeat(3, 152px); gap: 9px; }
