  .mod.hl { background: var(--c-focus-bg); color: var(--c-text); border: 1.5px solid var(--c-primary); font-weight: 700; }
  .mod.hl .sub { color: var(--c-muted); }
  /* 层间箭头 */
  .layer-arrow { text-align: center; color: var(--c-primary); font-size: 20px; line-height: 1; padding: 5px 0; }
</style>
</head>
